        vm.assume(caller != address(0) && beneficiary != address(0) && caller != beneficiary);
        vm.assume(mAssetAmount > 0 && mAssetAmount < 1e30);

        // Need an underlying token to transfer; we deploy a simple one
        // But we can't deploy extra contracts. Use a cheat to give caller tokens?
        // Instead: we can use the fact that underlying token is at address(0) initially.
        // Actually the constructor calls safeApprove on the underlying token, which reverts if token is zero address.
