pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(amount > 0 && amount < 1e30);

        // First, mint some mAsset to the caller and deposit
        address mAsset = address(c.mAsset());
        deal(mAsset, caller, amount);
        vm.prank(caller);
        (bool success, ) = mAsset.call(abi.encodeWithSignature("approve(address,uint256)", address(c), amount));
        require(success);
        vm.prank(caller);
        c.supplyTokenTo(amount, caller);

        // Get balances before approveMax
        uint256 imBalBefore = c.imBalances(caller);

        // Call approveMax
        c.approveMax();

        // After approveMax, redeem all underlying
        uint256 totalUnderlying = c.balanceOfToken(caller);
        c.redeemToken(totalUnderlying);

        // Get balances after
        uint256 imBalAfter = c.imBalances(caller);

        // The rule: after approveMax, calling redeemToken with the full underlying balance should reduce imBalances by the credits burned
        // For the reference contract, imBalAfter should be 0 (all credits burned)
        // For the mutant, imBalAfter should still be imBalBefore (since subtraction was 0)
        assertTrue(imBalAfter != imBalBefore, "imBalances should have changed after redeem");
    }
}

