        vm.deal(bob, 1e18);

        // Fund the contract with tokens (simplified: set up mAsset via deal)
        // Since we can't easily mint tokens, we'll use the contract's own balance
        vm.deal(address(c), 1e18);

        // Perform some deposits to create imBalances
        vm.prank(alice);
        c.supplyTokenTo(amountA, alice);
        vm.prank(bob);
