pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testFuzz_property(address spender) public {
        // Bound spender to avoid irrelevant reverts (just for general fuzzing)
        vm.assume(spender != address(0));

        // Call approveMax()
        c.approveMax();

        // After approveMax(), allowance should be type(uint256).max
        // Get the underlying token address from savings
        // We need to call allowance on the underlying token; we know savings.underlying() is the mAsset
        // The underlying token is IERC20; we can call allowance via c's public getters indirectly
        // But we need the address of the underlying token. We can get it via depositToken()
        address underlying = c.depositToken();
        // Now get the allowance that the savings contract has on behalf of C
        // We need an IERC20 interface for the underlying; we can use a low-level call or assume the mAsset is IERC20
        // Since we cannot import IERC20 again, we make a staticcall to the underlying token's allowance
        (bool success, bytes memory data) = underlying.staticcall(
            abi.encodeWithSignature("allowance(address,address)", address(c), address(c.savings()))
        );
        require(success, "allowance call failed");
        uint256 allowance = abi.decode(data, (uint256));

        assertTrue(allowance == type(uint256).max, "Allowance should be max after approveMax");
    }
}

